python - <<'PY'
import json,numpy as np
s=json.load(open('/app/output/spec.json')); E=np.array(s['cameras']['egocentric_mirrored_camera']['mount']['extrinsic_cv']); K=np.array(s['cameras']['egocentric_mirrored_camera']['intrinsic_cv']); d=np.load('/app/output/initial_depth_egocentric_mirrored_camera.npy')
inv=np.linalg.inv(E[:,:3]);
def pt(u,v):
 z=np.median(d[max(0,v-2):v+3,max(0,u-2):u+3]); c=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]); w=inv@(c-E[:,3]);return z,w
for p in [(350,205),(365,195),(370,220),(580,80),(575,95),(585,70),(450,250),(500,400),(250,300),(700,300),(150,300),(500,150)]: print(p,pt(*p))
# world points for tabletop grid
for v in [100,200,300,400]:
 print('v',v,[np.round(pt(u,v)[1],3).tolist() for u in [100,250,400,550,700,800]])
print('proprio and spec source saved')
PY

