import json,numpy as np
from PIL import Image
im=np.array(Image.open('/app/output/recovery_egocentric_mirrored_camera.png')).astype(int);d=np.load('/app/output/recovery_depth_egocentric_mirrored_camera.npy');s=json.load(open('/app/output/spec.json'));K=np.array(s['cameras']['egocentric_mirrored_camera']['intrinsic_cv']);E=np.array(s['cameras']['egocentric_mirrored_camera']['mount']['extrinsic_cv']); yy,xx=np.indices(d.shape);cam=np.stack([(xx-K[0,2])*d/K[0,0],(yy-K[1,2])*d/K[1,1],d],-1);world=(cam-E[:,3])@np.linalg.inv(E[:,:3]).T
for name,(x1,x2,y1,y2) in {'fallen':(600,700,270,375),'lower':(310,405,155,255)}.items():
 r=im[y1:y2,x1:x2]; xyz=world[y1:y2,x1:x2]; dep=d[y1:y2,x1:x2]; mask=(r.min(2)>120)&((r.max(2)-r.min(2))<90)&(dep>0)&(xyz[:,:,2]>.065);pts=xyz[mask]; print(name,len(pts));
 for k in range(3):print(k,np.round(np.percentile(pts[:,k],[5,25,50,75,95]),3))
 print('mean',np.round(pts.mean(0),3))
# IK candidate positions
